\title{Gamma--Poisson Duality and the Integer-Shape Descendant Limit Law for Random Recursive DAGs}
\author{Aristotle}
\date{2026-07-14}

\begin{document}

\begin{abstract}
For the random recursive directed acyclic graph (DAG) $G_n$ with fixed out-degree $d \ge 2$, the number $|D_n|$ of descendants of the root, once rescaled by $n^{1/d}$, converges in distribution to a Gamma law with shape parameter $d$ and rate $1$. Because the shape parameter is a positive integer, the limiting law is an Erlang distribution, whose cumulative distribution function admits a finite closed form. We prove --- by elementary real analysis alone --- the classical \emph{Gamma--Poisson duality} in this setting: the cumulative distribution function of $\Gam(m+1, 1)$ equals $1 - \sum_{k=0}^{m} e^{-t} t^k / k!$, and each summand is exactly a $\Poisson(t)$ point mass, so the survival function of the continuous Erlang limit is identically the tail of a discrete Poisson law. The proof rests on a single telescoping derivative identity together with the Fundamental Theorem of Calculus, and it simultaneously yields the closed-form cumulative distribution function, the fact that the Erlang density integrates to $1$, the decay of the survival function at infinity, and the monotonicity of the distribution function. We further record the moment structure of the limit target --- a rising-factorial sequence satisfying Carleman's condition, hence moment-determinate --- and the resulting equidispersion (variance equal to mean), interpreting it as an inherited Poisson fingerprint. We close with conjectures upgrading these facts to a uniform Poisson-tail representation of the full descendant distribution function and to a unified analytic description across all out-degrees $d \ge 1$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Random recursive DAGs and descendant counts}
A \emph{random recursive directed acyclic graph} (random $d$-DAG) with out-degree $d$ is built incrementally. One begins with a single root vertex labeled $1$. At each subsequent step $t = 2, 3, \dots, n$, a new vertex $t$ is added, and $d$ distinct vertices are chosen uniformly at random from among the existing vertices $\{1, \dots, t-1\}$ (for $t \le d$ one takes all available predecessors); vertex $t$ sends an arc to each chosen vertex. The result is a directed acyclic graph on $n$ vertices in which all arcs point from higher labels to lower labels, so no cycle is possible.

These graphs formalize a widely used modeling idiom: each newly created object depends on several previously existing objects. Concrete instances include software module dependency graphs, citation networks with a fixed citation budget, versioned artifact lineages, and directed-acyclic-graph ledgers. The case $d = 1$ recovers the classical random recursive \emph{tree}.

Fix the root and let $D_n$ denote the set of vertices from which the root is reachable --- the \emph{descendants} of the root --- and $|D_n|$ its cardinality. The asymptotics of $|D_n|$ quantify how much of a large recursive network ultimately traces back to its origin.

\subsection{The scaling limit}
For $d = 1$ the descendant count grows linearly in $n$. For $d \ge 2$ the requirement that \emph{all} backward paths route through the root suppresses the count to sublinear order $n^{1/d}$.

\begin{theorem}[Descendant limit law]\label{thm:dll}
For the random recursive DAG with out-degree $d \ge 2$,
\[
\frac{|D_n|}{n^{1/d}} \xrightarrow{\ d\ } \Gam(d, 1) \qquad (n \to \infty),
\]
where $\Gam(d,1)$ is the distribution on $(0,\infty)$ with density $f_d(x) = x^{d-1} e^{-x} / \Gamma(d)$.
\end{theorem}

Theorem~\ref{thm:dll} is the backdrop for this paper; our contribution concerns the fine structure of the integer-shape limit target $\Gam(d,1)$.

\subsection{Contributions}
We establish, by elementary and fully rigorous real analysis:
(1) a telescoping derivative identity for Poisson point masses viewed as functions of the continuous parameter (Section~\ref{sec:telescope});
(2) the Gamma--Poisson duality, a finite closed form for the Erlang cumulative distribution function exhibiting it as a Poisson tail (Section~\ref{sec:duality});
(3) three corollaries: the survival function vanishes at infinity, the Erlang density integrates to $1$, and the distribution function is monotone (Section~\ref{sec:corollaries});
(4) the moment structure of the limit law: rising-factorial moments, moment-determinacy via Carleman's condition, and equidispersion (Section~\ref{sec:moments}).

\section{Definitions and notation}
Throughout, $m$ denotes a nonnegative integer and $t, x$ real variables. We write $\Gamma$ for the Euler Gamma function, with $\Gamma(m+1) = m!$.

\begin{definition}[Poisson term]
For $k \in \N$ and $t \in \R$, the \emph{Poisson term} is
\[
p_k(t) := \frac{e^{-t}\, t^{k}}{k!}.
\]
As a function of the discrete index $k$, $\{p_k(t)\}_{k \ge 0}$ is the probability mass function of the $\Poisson(t)$ distribution; as a function of the continuous variable $t$, $p_m$ is proportional to the $\Gam(m+1, 1)$ density.
\end{definition}

\begin{definition}[Erlang survival sum]
For $n \in \N$ and $t \in \R$,
\[
S_n(t) := \sum_{k=0}^{n-1} p_k(t) = \sum_{k=0}^{n-1} \frac{e^{-t} t^k}{k!}.
\]
For $t \ge 0$ this equals the lower Poisson tail $\Prob(\Poisson(t) \le n-1)$.
\end{definition}

\begin{definition}[Gamma density]
The $\Gam(a, 1)$ density on $(0, \infty)$ is $g_a(x) = x^{a-1} e^{-x} / \Gamma(a)$. For integer shape $a = m+1$ this is the \emph{Erlang} density.
\end{definition}

\begin{lemma}[Term equals Gamma density]\label{lem:termgamma}
For every $m \in \N$ and $x \in \R$, $p_m(x) = e^{-x} x^m / \Gamma(m+1)$.
\end{lemma}
\begin{proof}
Immediate from $\Gamma(m+1) = m!$.
\end{proof}

All integrals below are with respect to Lebesgue measure; densities are on $(0, \infty)$.

\section{The telescoping derivative identity}\label{sec:telescope}

\begin{lemma}[Telescoping step]\label{lem:step}
For every $m \in \N$ and $t \in \R$, $p_{m+1}$ is differentiable at $t$ with
\[
p_{m+1}'(t) = p_m(t) - p_{m+1}(t).
\]
\end{lemma}
\begin{proof}
By the product rule, using $\tfrac{d}{dt} e^{-t} = -e^{-t}$ and $\tfrac{d}{dt} t^{m+1} = (m+1) t^m$,
\[
p_{m+1}'(t) = \frac{-e^{-t} t^{m+1} + (m+1) e^{-t} t^m}{(m+1)!} = \frac{e^{-t} t^m}{m!} - \frac{e^{-t} t^{m+1}}{(m+1)!} = p_m(t) - p_{m+1}(t),
\]
using $(m+1)!/(m+1) = m!$.
\end{proof}

\begin{lemma}[Base case]\label{lem:base}
For every $t \in \R$, $p_0(t) = e^{-t}$ satisfies $p_0'(t) = -p_0(t)$.
\end{lemma}

\begin{theorem}[Derivative of the survival sum]\label{thm:survderiv}
For every $m \in \N$ and $t \in \R$,
\[
S_{m+1}'(t) = -p_m(t) = -\frac{e^{-t} t^m}{m!}.
\]
That is, the derivative of the Erlang survival sum is minus the Erlang density.
\end{theorem}
\begin{proof}
Induction on $m$. For $m = 0$, $S_1 = p_0$ and Lemma~\ref{lem:base} gives $S_1'(t) = -p_0(t)$. For the step, $S_{m+2}(t) = S_{m+1}(t) + p_{m+1}(t)$, so by the inductive hypothesis and Lemma~\ref{lem:step},
\[
S_{m+2}'(t) = -p_m(t) + \big(p_m(t) - p_{m+1}(t)\big) = -p_{m+1}(t). \qedhere
\]
\end{proof}

The interior term $p_m(t)$ produced by differentiating $p_{m+1}$ cancels the $-p_m(t)$ from the inductive hypothesis; this cancellation is the telescope.

\begin{lemma}[Continuity]\label{lem:cont}
Each $p_k$ is continuous on $\R$.
\end{lemma}

\begin{lemma}[Value at zero]\label{lem:zero}
For $n \ge 1$, $S_n(0) = 1$.
\end{lemma}
\begin{proof}
At $t = 0$ only the $k = 0$ term is nonzero, and $p_0(0) = 1$.
\end{proof}

\section{The Gamma--Poisson duality}\label{sec:duality}

\begin{theorem}[Erlang CDF; Gamma--Poisson duality]\label{thm:duality}
For every $m \in \N$ and every $t \in \R$,
\[
\int_0^t \frac{e^{-x} x^m}{m!}\, dx = 1 - S_{m+1}(t) = 1 - \sum_{k=0}^{m} \frac{e^{-t} t^k}{k!}.
\]
Equivalently, for $t \ge 0$,
\[
\Prob\big(\Gam(m+1, 1) \le t\big) = 1 - \Prob\big(\Poisson(t) \le m\big) = \Prob\big(\Poisson(t) \ge m+1\big).
\]
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:survderiv}, $S_{m+1}$ has derivative $-p_m$ throughout the interval between $0$ and $t$; $p_m$ is continuous (Lemma~\ref{lem:cont}), hence interval-integrable. The Fundamental Theorem of Calculus gives
\[
\int_0^t \big(-p_m(x)\big)\, dx = S_{m+1}(t) - S_{m+1}(0).
\]
Negating and using $S_{m+1}(0) = 1$ (Lemma~\ref{lem:zero}) yields $\int_0^t p_m(x)\, dx = 1 - S_{m+1}(t)$. By Lemma~\ref{lem:termgamma} the integrand is the $\Gam(m+1,1)$ density and each summand of $S_{m+1}$ is a $\Poisson(t)$ mass.
\end{proof}

\begin{remark}[Probabilistic reading]
The identity is the analytic shadow of a fact about a rate-$1$ Poisson process: the waiting time until the $(m+1)$-st arrival is $\Erlang(m+1)$, while the count of arrivals in $[0, t]$ is $\Poisson(t)$. The events $\{(m{+}1)\text{-st arrival} \le t\}$ and $\{\ge m{+}1 \text{ arrivals by } t\}$ coincide, and equating their probabilities is Theorem~\ref{thm:duality}.
\end{remark}

\section{Corollaries: a genuine probability law}\label{sec:corollaries}

\begin{lemma}[Termwise decay]\label{lem:decay}
For each $k$, $p_k(t) \to 0$ as $t \to \infty$.
\end{lemma}

\begin{theorem}[Survival function vanishes at infinity]\label{thm:survzero}
For every $n$, $S_n(t) \to 0$ as $t \to \infty$.
\end{theorem}
\begin{proof}
$S_n$ is a finite sum of the $p_k$, each null at infinity by Lemma~\ref{lem:decay}.
\end{proof}

\begin{theorem}[The Erlang density is a probability density]\label{thm:norm}
For every $m$, $\int_0^\infty e^{-x} x^m / m!\, dx = 1$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:duality} the cumulative integral equals $1 - S_{m+1}(t)$; by Theorem~\ref{thm:survzero}, $S_{m+1}(t) \to 0$, so the integral tends to $1$.
\end{proof}

\begin{theorem}[Monotonicity of the distribution function]\label{thm:mono}
The map $t \mapsto \int_0^t p_m(x)\, dx$ is nondecreasing on $[0, \infty)$.
\end{theorem}
\begin{proof}
For $0 \le a \le b$, additivity gives $\int_0^b p_m = \int_0^a p_m + \int_a^b p_m$, and $\int_a^b p_m \ge 0$ since $p_m \ge 0$.
\end{proof}

\section{Moment structure of the limit law}\label{sec:moments}

\begin{proposition}[Rising-factorial moments]\label{prop:moments}
The $k$-th moment of $\Gam(d, 1)$ is
\[
m_k := \E\big[\Gam(d,1)^k\big] = \frac{\Gamma(d + k)}{\Gamma(d)} = \prod_{i=0}^{k-1}(d + i),
\]
with recurrence $m_{k+1} = (d + k)\, m_k$ and $m_0 = 1$.
\end{proposition}

In particular $m_1 = d$, $m_2 = d(d+1)$, and $\Var = m_2 - m_1^2 = d$.

\begin{proposition}[Equidispersion]\label{prop:equi}
For every $d$, the mean and variance of $\Gam(d, 1)$ coincide, both equal to $d$.
\end{proposition}

Equidispersion is the defining fingerprint of the Poisson distribution; its appearance here is the moment-level trace of the Poisson layer exposed by the Gamma--Poisson duality.

\begin{proposition}[Moment determinacy]\label{prop:carleman}
The moment sequence $\{m_k\}$ satisfies Carleman's condition $\sum_{k \ge 1} m_{2k}^{-1/(2k)} = \infty$; hence $\Gam(d,1)$ is uniquely determined by its moments.
\end{proposition}
\begin{proof}[Sketch]
Since $m_{2k} = \Gamma(d+2k)/\Gamma(d)$, Stirling gives $(\Gamma(d+2k))^{1/(2k)} = \Theta(k)$, so $m_{2k}^{-1/(2k)} = \Theta(1/k)$ and the series diverges harmonically. Carleman's condition yields determinacy.
\end{proof}

Consequently the method of moments --- matching the moments of $|D_n|/n^{1/d}$ to $\prod_{i<k}(d+i)$ --- is a valid proof of convergence, not merely suggestive.

\section{Algorithms}

\begin{algorithm}[Exact Erlang CDF via Poisson tail]
To compute $F_d(t) = \Prob(\Gam(d,1) \le t)$ for integer $d$: accumulate $p_0(t), \dots, p_{d-1}(t)$ by the stable recurrence $p_0 = e^{-t}$, $p_k = p_{k-1}\cdot t/k$; sum to get $S_d(t)$; return $1 - S_d(t)$. Cost $O(d)$, no integration.
\end{algorithm}

\begin{algorithm}[Descendant-count tail probability]
To estimate $\Prob(|D_n| \le c\, n^{1/d})$ for large $n$, apply Theorem~\ref{thm:dll} and the previous algorithm with $t = c$: the answer is $\approx 1 - \sum_{k=0}^{d-1} e^{-c} c^k / k!$.
\end{algorithm}

\section{Applications and discussion}

The finite Poisson-tail formula gives instant threshold and quantile computations for the root's descendant count, transfers the mature Erlang/Poisson theory (queueing, telecommunications, reliability) to lineage structure of dependency graphs, citation webs, and DAG ledgers, and provides an equidispersion diagnostic ($\Var/\text{mean} \approx 1$ after rescaling) for the random-$d$-DAG universality class.

The results assemble a three-layer picture: the combinatorial descendant count $|D_n|$; its continuous $\Gam(d,1)$ scaling limit; and, because $d$ is an integer, a finite Poisson tail equal to the Erlang distribution function. The duality is the hinge between the last two, and its proof is economical: one telescoping derivative, the Fundamental Theorem of Calculus, one induction, one limit. The finite form is special to integer shape; for non-integer shape the CDF is the incomplete Gamma function with no finite Poisson-tail form --- but the integer case is exactly the one relevant here.

\section{Future directions}

\begin{conjecture}[Poisson-tail representation of the full descendant CDF]
For integer $d \ge 2$, the limiting distribution function of $|D_n|/n^{1/d}$ is exactly $t \mapsto \Prob(\Poisson(t) \ge d)$, and the convergence of distribution functions is uniform on the half-line.
\end{conjecture}

\begin{conjecture}[Moment determinacy of the limit law]
The moment sequence $m_k = \prod_{i<k}(d+i)$ satisfies Carleman's condition, so it uniquely determines the limit distribution; consequently the method of moments is valid for the descendant limit theorem.
\end{conjecture}

\begin{conjecture}[Variance-to-mean rigidity]
Across all $d \ge 1$, the limit law has variance equal to its mean (both $= d$), an equidispersion inherited from the Poisson layer exposed by the duality rather than from the DAG geometry.
\end{conjecture}

\begin{conjecture}[Interpolating the tree and DAG regimes]
The scaling exponent $1/d$ and constant $1/\Gamma(1 + 1/d)$ of the mean-growth product vary analytically in $d \ge 1$, interpolating continuously between the linear growth of the random recursive tree ($d = 1$) and the $n^{1/d}$ regime ($d \ge 2$), with no phase transition at $d = 1$.
\end{conjecture}

