"""Gamma-Poisson duality verification.

Confirms P(Gamma(m+1,1) <= t) = 1 - sum_{k=0}^m e^{-t} t^k/k! by comparing the
finite Poisson-tail closed form against direct Simpson integration of the Erlang
density e^{-x} x^m / m! on [0, t].
"""
from __future__ import annotations
import math
from typing import Callable


def poisson_term(k: int, t: float) -> float:
    return math.exp(-t) * t ** k / math.factorial(k)


def erlang_cdf_closed_form(m: int, t: float) -> float:
    """P(Gamma(m+1,1) <= t) = 1 - sum_{k<=m} poisson_term(k, t)."""
    if t <= 0:
        return 0.0
    return 1.0 - sum(poisson_term(k, t) for k in range(m + 1))


def erlang_cdf_integrated(m: int, t: float, steps: int = 20000) -> float:
    if t <= 0:
        return 0.0
    fact = math.factorial(m)
    f: Callable[[float], float] = lambda x: math.exp(-x) * x ** m / fact
    h = t / steps
    total = f(0.0) + f(t)
    for i in range(1, steps):
        total += (4.0 if i % 2 else 2.0) * f(i * h)
    return total * h / 3.0


if __name__ == "__main__":
    print(f"{'m':>3} {'t':>6} {'closed form':>14} {'integrated':>14} {'|diff|':>10}")
    for m, t in [(0, 1.0), (1, 2.0), (2, 3.0), (3, 5.0), (4, 6.5)]:
        a = erlang_cdf_closed_form(m, t)
        b = erlang_cdf_integrated(m, t)
        print(f"{m:>3} {t:>6.2f} {a:>14.10f} {b:>14.8f} {abs(a-b):>10.2e}")

"""Sampling the limit law Gamma(d,1) = Erlang(d) as a sum of exponentials.

Erlang(d) is the time of the d-th arrival in a rate-1 Poisson process: the sum of
d independent Exp(1) inter-arrival times. We draw many samples and compare the
empirical CDF against the exact Poisson-tail formula 1 - sum_{k<d} e^{-t} t^k/k!.
"""
from __future__ import annotations
import math
import random


def poisson_term(k: int, t: float) -> float:
    return math.exp(-t) * t ** k / math.factorial(k)


def erlang_cdf(d: int, t: float) -> float:
    """P(Gamma(d,1) <= t) = 1 - sum_{k<d} poisson_term(k, t)."""
    if t <= 0:
        return 0.0
    return 1.0 - sum(poisson_term(k, t) for k in range(d))


def sample_erlang(d: int, rng: random.Random) -> float:
    return sum(rng.expovariate(1.0) for _ in range(d))


if __name__ == "__main__":
    rng = random.Random(7)
    for d in (2, 3, 4):
        xs = [sample_erlang(d, rng) for _ in range(200000)]
        mean = sum(xs) / len(xs)
        var = sum((x - mean) ** 2 for x in xs) / len(xs)
        print(f"d={d}: empirical mean={mean:.4f} (={d}), variance={var:.4f} (={d})")
        xs.sort()
        for t in (0.5 * d, float(d), 1.5 * d):
            emp = sum(1 for x in xs if x <= t) / len(xs)
            print(f"   t={t:5.2f}  empirical CDF={emp:.4f}  exact={erlang_cdf(d, t):.4f}")

