function ERLANG_CDF_POISSON_TAIL(d, t):
    if t <= 0: return 0
    term <- exp(-t)          # p_0
    survival <- term         # S_1
    for k from 1 to d-1:
        term <- term * t / k # p_k = p_{k-1} * t / k
        survival <- survival + term
    return 1 - survival      # = P(Gamma(d,1) <= t) = P(Poisson(t) >= d)

function DESCENDANT_TAIL_PROBABILITY(d, n, c):
    # limit value depends only on d and c
    if c <= 0: return 0
    term <- exp(-c)
    survival <- term
    for k from 1 to d-1:
        term <- term * c / k
        survival <- survival + term
    return 1 - survival   # approx P(|D_n| <= c * n^{1/d})

function GAMMA_MOMENTS(d, kmax):
    moments <- [1]              # m_0
    for k from 0 to kmax-1:
        moments.append((d + k) * moments[last])  # m_{k+1} = (d+k) m_k
    return moments             # [m_0, ..., m_kmax]
